/* R1368 — additive promotion preview and media-management completeness */
(()=>{'use strict';
const API='https://franklin-navigator-membership.onrender.com',q=(s,r=document)=>r.querySelector(s);let urls=[],timer=0,lastProfile='';
const isEs=()=>window.FranklinI18n?.language==='es'||localStorage.getItem('franklinLanguage')==='es';
const T=(en,es)=>isEs()?es:en;
function clearUrls(){for(const u of urls)URL.revokeObjectURL(u);urls=[]}
async function req(path,opts={}){const r=await fetch(API+path,{credentials:'include',cache:'no-store',...opts,headers:opts.body?{'Content-Type':'application/json',...(opts.headers||{})}:opts.headers});let out={};try{out=await r.json()}catch{}if(!r.ok)throw new Error(out?.error?.message||out?.message||T('We could not complete that request.','No pudimos completar esa solicitud.'));return out}
const label=k=>({COUPON:T('Coupon','Cupón'),SPECIAL:T('Special offer','Oferta especial'),SALE:T('Sale','Venta'),PROMOTION:T('Promotion','Promoción'),EVENT:T('Event','Evento')}[k]||k);
function line(box,strong,value){if(!value)return;const p=document.createElement('p'),b=document.createElement('strong');b.textContent=strong;p.append(b,document.createTextNode(String(value)));box.append(p)}
function button(text,fn,primary=false){const b=document.createElement('button');b.type='button';b.className='button'+(primary?' primary':'');b.textContent=text;b.addEventListener('click',fn);return b}
function itemPreview(item,media){const card=document.createElement('article');card.className='r1368-preview-card';const eye=document.createElement('div');eye.className='eyebrow';eye.textContent=T('Resident preview','Vista previa para residentes');const h=document.createElement('h3');h.textContent=item.title;const d=document.createElement('p');d.textContent=item.description;card.append(eye,h,d);line(card,T('Type: ','Tipo: '),label(item.kind));line(card,T('Code: ','Código: '),item.promo_code);line(card,T('Offer: ','Oferta: '),item.discount_text);line(card,T('Starts: ','Comienza: '),item.start_at?new Date(item.start_at).toLocaleString():'');line(card,T('Ends: ','Termina: '),item.end_at?new Date(item.end_at).toLocaleString():'');line(card,T('Location: ','Ubicación: '),item.event_location);if(item.action_url){const a=document.createElement('a');a.href=item.action_url;a.target='_blank';a.rel='noopener';a.textContent=T('Open public action link','Abrir enlace público de acción');card.append(a)}const m=media.filter(x=>x.promotion_id===item.promotion_id);const note=document.createElement('p');note.className='fine-print';note.textContent=m.length?T(`${m.length} attached media item${m.length===1?'':'s'}. Preview or manage it below.`,`${m.length} elemento${m.length===1?'':'s'} multimedia adjunto${m.length===1?'':'s'}. Previsualícelo o adminístrelo abajo.`):T('No promotional media attached yet.','Aún no hay contenido promocional adjunto.');card.append(note);return card}
async function previewMedia(m,row){const old=q('[data-r1368-media-preview]',row);if(old){old.remove();return}const r=await fetch(API+m.previewUrl,{credentials:'include',cache:'no-store'});if(!r.ok)throw new Error(T('This media preview is not available right now.','Esta vista previa no está disponible en este momento.'));const blob=await r.blob(),u=URL.createObjectURL(blob);urls.push(u);const box=document.createElement('div');box.className='r1368-media-preview';box.dataset.r1368MediaPreview='';if((m.mime_type||'').toLowerCase()==='application/pdf'){const a=document.createElement('a');a.href=u;a.target='_blank';a.rel='noopener';a.className='button';a.textContent=T('Open PDF preview','Abrir vista previa del PDF');box.append(a)}else{const img=document.createElement('img');img.src=u;img.alt=T('Preview of your promotional media','Vista previa de su contenido promocional');img.loading='lazy';box.append(img)}row.append(box)}
async function removeMedia(m){if(!confirm(T('Remove this promotional media?','¿Eliminar este contenido promocional?')))return;const profile=currentProfile();await req('/api/member/promotions/media/remove?profileId='+encodeURIComponent(profile),{method:'POST',body:JSON.stringify({mediaId:m.media_id})});await refresh(true)}
function replaceMedia(m){const f=q('[data-r1365-media-form]');if(!f)return;f.elements.promotionId.value=m.promotion_id;f.elements.mediaKind.value=m.media_kind;f.scrollIntoView({behavior:'smooth',block:'start'});f.elements.file?.focus()}
function mediaRow(m,items){const row=document.createElement('article');row.className='r1368-media-row';const h=document.createElement('strong');h.textContent=String(m.media_kind||'').replaceAll('_',' ');const meta=document.createElement('p');meta.className='fine-print';const item=items.find(x=>x.promotion_id===m.promotion_id);meta.textContent=`${m.state} · ${Math.round((m.byte_size||0)/1024)} KB${item?' · '+item.title:''}`;const actions=document.createElement('div');actions.className='r1365-actions';actions.append(button(T('Preview media','Vista previa del contenido'),()=>previewMedia(m,row).catch(showError)));if(m.state!=='SUBMITTED')actions.append(button(T('Remove media','Eliminar contenido'),()=>removeMedia(m).catch(showError)));actions.append(button(T('Replace media','Reemplazar contenido'),()=>replaceMedia(m)));row.append(h,meta,actions);return row}
function currentProfile(){return q('[data-r1365-profile-picker] select')?.value||''}
function showError(e){const s=q('[data-r1365-status]');if(s){s.textContent=e.message;s.className='r1365-status warn'}}
async function refresh(force=false){const root=q('[data-r1368-preview-workspace]'),profile=currentProfile();if(!root||!profile)return;if(!force&&profile===lastProfile&&root.dataset.loaded==='1')return;lastProfile=profile;root.dataset.loaded='0';root.hidden=false;root.textContent=T('Loading preview and media controls…','Cargando vista previa y controles multimedia…');try{const [a,b]=await Promise.all([req('/api/member/promotions/list?profileId='+encodeURIComponent(profile)),req('/api/member/promotions/media/list?profileId='+encodeURIComponent(profile))]);clearUrls();root.replaceChildren();const eye=document.createElement('div');eye.className='eyebrow';eye.textContent=T('Preview before publication','Vista previa antes de publicar');const h=document.createElement('h2');h.textContent=T('Review what residents will understand','Revise lo que entenderán los residentes');const intro=document.createElement('p');intro.textContent=T('Preview your offer or event details, then preview, replace or remove its attached promotional media before or after review.','Previsualice los detalles de su oferta o evento y luego previsualice, reemplace o elimine el contenido promocional adjunto antes o después de la revisión.');root.append(eye,h,intro);const items=a.promotions||[],media=b.media||[];if(!items.length){const p=document.createElement('p');p.textContent=T('Create a draft above to start a resident preview.','Cree un borrador arriba para iniciar una vista previa para residentes.');root.append(p)}else{const grid=document.createElement('div');grid.className='r1368-preview-grid';items.forEach(i=>grid.append(itemPreview(i,media)));root.append(grid)}const mh=document.createElement('h3');mh.textContent=T('Attached promotional media','Contenido promocional adjunto');root.append(mh);if(!media.length){const p=document.createElement('p');p.textContent=T('No promotional graphics, flyer images or PDF documents are attached yet.','Aún no hay gráficos promocionales, imágenes de volantes ni documentos PDF adjuntos.');root.append(p)}else{const list=document.createElement('div');list.className='r1368-media-grid';media.forEach(m=>list.append(mediaRow(m,items)));root.append(list)}root.dataset.loaded='1'}catch(e){root.hidden=true;showError(e)}}
function schedule(force=false){clearTimeout(timer);timer=setTimeout(()=>refresh(force),120)}
document.addEventListener('DOMContentLoaded',()=>{const status=q('[data-r1365-status]');if(status)new MutationObserver(()=>{if(/tools are ready|herramientas.*listas/i.test(status.textContent))schedule(true)}).observe(status,{childList:true,subtree:true,characterData:true});const wait=setInterval(()=>{const sel=q('[data-r1365-profile-picker] select');if(!sel)return;clearInterval(wait);sel.addEventListener('change',()=>schedule(true));schedule(true)},120);setTimeout(()=>clearInterval(wait),10000);document.querySelectorAll('[data-r37-lang]').forEach(b=>b.addEventListener('click',()=>setTimeout(()=>schedule(true),0)))})
})();
